extension ProviderPresetLlmMapping on ProviderPreset {
  fa_llm.LlmConfig? toDefaultLlmConfig() {
    final url = baseUrl;
    if (url == null) return null;
    return fa_llm.LlmConfig(
      providerName: _providerNameFor(name),
