}

String _providerNameFor(String providerKind) {
  return switch (providerKind.toLowerCase()) {
    'openrouter' => 'openrouter',
    'ollama' || 'ollama-cloud' => 'ollama',
    'openai' || 'openai-completions' => 'openai',
    'copilot' => 'copilot',
    _ => 'openai',
