  @override
  Future<String> chatMessages(
    List<LlmMessage> messages, {
    String? model,
    void Function()? onCancel,
  }) async {
    final slot = resolve();
    if (slot == null) {
      onCancel?.call();
      throw StateError(
        'HarnessLlmProvider: no LLM slot resolved (roles unavailable)',
