      expect(resolve('openai', 'http://127.0.0.1:8931/v1/'),
          'http://127.0.0.1:8931/v1/chat/completions');
    });

    test('empty override stays empty for the factory default fallback', () {
      expect(resolve('openai', ''), '');
    });
