extension FaChatModelConfigLlmMapping on FaChatModelConfig {
  fa_llm.LlmConfig toLlmConfig() {
    return fa_llm.LlmConfig(
      providerName: _providerNameFor(providerKind),
      apiKey: [REDACTED:Sensitive Value],
      baseUrl: baseUrl,
