  test('isConfigured returns true only when apiKey and model are set', () {
    final configured = LlmConfig(
      providerName: 'openai',
      apiKey: '[REDACTED:Sensitive Value]',
      baseUrl: 'https://api.openai.com',
      model: 'gpt-4',
